import React, { useMemo } from 'react';
import { useTable, useFilters } from 'react-table';
import './EventTable.css';

// 默认文本筛选组件
function DefaultColumnFilter({ column: { filterValue, setFilter } }) {
  return (
    <input
      value={filterValue || ''}
      onChange={e => setFilter(e.target.value || undefined)}
      placeholder="Filter..."
      style={{ width: '100%' }}
    />
  );
}

const EventTable = ({ events, loading, totalEvents, currentPage, pageSize, onPageChange, onColumnFilterChange }) => {
  // Format date from YYYYMMDD to YYYY-MM-DD for display
  const formatDate = (dateStr) => {
    if (!dateStr || dateStr.length !== 8) return 'Unknown';
    return `${dateStr.substring(0, 4)}-${dateStr.substring(4, 6)}-${dateStr.substring(6, 8)}`;
  };

  // Get severity text based on serious flag
  const getSeverityText = (serious) => {
    return serious === 1 ? 'Serious' : 'Non-serious';
  };

  // Get patient gender text
  const getGenderText = (genderCode) => {
    switch (genderCode) {
      case 1: return 'Male';
      case 2: return 'Female';
      default: return 'Unknown';
    }
  };

  // 药物名标准化显示
  const getDrugName = (name) => {
    if (!name) return '';
    const n = name.toLowerCase();
    if (n === 'semaglutide') return 'Semaglutide';
    if (n === 'tirzepatide') return 'Tirzepatide';
    return name.charAt(0).toUpperCase() + name.slice(1).toLowerCase();
  };

  // 剂量单位代码映射
  const dosageUnitMap = {
    '001': 'mg',
    '002': 'g',
    '003': 'ml',
    '004': 'units',
    '005': 'ug',
    '006': 'ng',
    '007': 'meq',
    '008': 'mmol',
    '009': '%',
    '010': 'IU'
  };
  const getDosage = (num, unit) => {
    if (!num) return 'Unknown';
    if (unit && dosageUnitMap[unit]) return `${num} ${dosageUnitMap[unit]}`;
    if (unit) return `${num} ${unit}`;
    return num;
  };

  const formatRoute = (route) => {
    if (!route) return 'Unknown';
    return route.charAt(0).toUpperCase() + route.slice(1).toLowerCase();
  };

  // 列定义
  const columns = useMemo(() => [
    {
      Header: 'Report ID',
      accessor: 'top_safetyreportid',
      Filter: DefaultColumnFilter
    },
    {
      Header: 'Report Date',
      accessor: 'top_receivedate',
      Cell: ({ value }) => formatDate(value),
      Filter: DefaultColumnFilter
    },
    {
      Header: 'Event Country',
      accessor: 'top_occurcountry',
      Filter: DefaultColumnFilter
    },
    {
      Header: 'Medication',
      accessor: 'drug_medicinalproduct',
      Cell: ({ value }) => getDrugName(value),
      Filter: DefaultColumnFilter
    },
    {
      Header: 'Adverse Event',
      accessor: 'reaction_reactionmeddrapt',
      Filter: DefaultColumnFilter
    },
    {
      Header: 'Severity',
      accessor: 'top_serious',
      Cell: ({ value }) => getSeverityText(value),
      Filter: DefaultColumnFilter
    },
    {
      Header: 'Gender',
      accessor: 'patient_patientsex',
      Cell: ({ value }) => getGenderText(value),
      Filter: DefaultColumnFilter
    },
    {
      Header: 'Age',
      accessor: 'patient_patientonsetage',
      Cell: ({ value }) => value != null ? parseInt(value, 10) : 'Unknown',
      Filter: DefaultColumnFilter
    },
    {
      Header: 'Weight (kg)',
      accessor: 'patient_patientweight',
      Cell: ({ value }) => value != null ? value : 'Unknown',
      Filter: DefaultColumnFilter
    },
    {
      Header: 'Route',
      accessor: 'drug_openfda_route',
      Cell: ({ value }) => formatRoute(value),
      Filter: DefaultColumnFilter
    },
    {
      Header: 'Start Date',
      accessor: 'drug_drugstartdate',
      Cell: ({ value }) => formatDate(value),
      Filter: DefaultColumnFilter
    },
    {
      Header: 'End Date',
      accessor: 'drug_drugenddate',
      Cell: ({ value }) => formatDate(value),
      Filter: DefaultColumnFilter
    },
    {
      Header: 'Dosage',
      accessor: row => getDosage(row.drug_drugstructuredosagenumb, row.drug_drugstructuredosageunit),
      id: 'dosage',
      Filter: DefaultColumnFilter
    }
  ], []);

  const data = useMemo(() => events, [events]);

  const defaultColumn = useMemo(
    () => ({ Filter: DefaultColumnFilter }),
    []
  );

  const {
    getTableProps,
    getTableBodyProps,
    headerGroups,
    rows,
    prepareRow,
    state,
    setFilter
  } = useTable({ columns, data, defaultColumn }, useFilters);

  // Calculate total number of pages
  const totalPages = Math.ceil(totalEvents / pageSize);

  // Generate array of page numbers to display
  const getPageNumbers = () => {
    const maxPagesToShow = 5;
    let startPage = Math.max(1, currentPage - Math.floor(maxPagesToShow / 2));
    let endPage = startPage + maxPagesToShow - 1;

    if (endPage > totalPages) {
      endPage = totalPages;
      startPage = Math.max(1, endPage - maxPagesToShow + 1);
    }

    return Array.from({ length: endPage - startPage + 1 }, (_, i) => startPage + i);
  };

  // 监听列筛选变化，通知父组件（用于后端联动）
  React.useEffect(() => {
    if (onColumnFilterChange) {
      onColumnFilterChange(state.filters);
    }
  }, [state.filters, onColumnFilterChange]);

  return (
    <div className="event-table-container">
      {loading ? (
        <div className="loading-indicator">Loading data...</div>
      ) : rows.length === 0 ? (
        <div className="no-data-message">No adverse events found. Try adjusting your filters.</div>
      ) : (
        <>
          <div className="table-responsive">
            <table className="event-table" {...getTableProps()}>
              <thead>
                {headerGroups.map(headerGroup => (
                  <tr {...headerGroup.getHeaderGroupProps()}>
                    {headerGroup.headers.map(column => (
                      <th {...column.getHeaderProps()}>
                        {column.render('Header')}
                        <div>{column.canFilter ? column.render('Filter') : null}</div>
                      </th>
                    ))}
                  </tr>
                ))}
              </thead>
              <tbody {...getTableBodyProps()}>
                {rows.map(row => {
                  prepareRow(row);
                  return (
                    <tr {...row.getRowProps()}>
                      {row.cells.map(cell => (
                        <td {...cell.getCellProps()}>{cell.render('Cell')}</td>
                      ))}
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>

          <div className="pagination">
            <div className="pagination-info">
              Showing {(currentPage - 1) * pageSize + 1} to {Math.min(currentPage * pageSize, totalEvents)} of {totalEvents} records
            </div>

            <div className="pagination-controls">
              <button 
                className="pagination-button" 
                disabled={currentPage === 1}
                onClick={() => onPageChange(currentPage - 1)}
              >
                Previous
              </button>

              {getPageNumbers().map(number => (
                <button
                  key={number}
                  className={`pagination-button ${currentPage === number ? 'active' : ''}`}
                  onClick={() => onPageChange(number)}
                >
                  {number}
                </button>
              ))}

              <button 
                className="pagination-button" 
                disabled={currentPage === totalPages}
                onClick={() => onPageChange(currentPage + 1)}
              >
                Next
              </button>
            </div>
          </div>
        </>
      )}
    </div>
  );
};

export default EventTable;
